INSERT INTO order_log (
    order_id, signal_id, stock_code, trading_mode, order_type,
    quantity, order_price, executed_price, execution_status,
    blocked_by_risk_id, kiwoom_order_no
) VALUES (
    #{orderId}, #{signalId}, #{stockCode}, #{tradingMode}, #{orderType},
    #{quantity}, #{orderPrice}, #{executedPrice}, #{executionStatus},
    #{blockedByRiskId}, #{kiwoomOrderNo}
)

mapper.select:
SELECT COALESCE(SUM(executed_price * quantity), 0)
FROM order_log
WHERE trading_mode = #{tradingMode}
  AND order_type = #{orderType}
  AND execution_status = 'FILLED'
  AND deleted_at IS NULL

SELECT MAX(created_at)
FROM order_log
WHERE stock_code = #{stockCode}
  AND trading_mode = #{tradingMode}
  AND deleted_at IS NULL

SELECT COUNT(*)
FROM order_log
WHERE trading_mode = #{tradingMode}
  AND created_at >= #{since}
  AND deleted_at IS NULL
